static int YARVM_vw_token(const char **source, char *out, size_t capacity) {
  const char *p=*source; size_t count=0;
  for(;;) {
    while(*p && isspace((unsigned char)*p)) ++p;
    if(*p!='#') break;
    while(*p && *p!='\n') ++p;
  }
  if(!*p) { *source=p; return 0; }
  while(*p && !isspace((unsigned char)*p) && *p!='#') {
    if(count+1>=capacity) return -1;
    out[count++]=*p++;
  }
  out[count]=0; *source=p; return 1;
}
static const YARVM_metadata *YARVM_vw_mnemonic(const char *name) {
  if(strcmp(name,"BRANCHIF")==0) return YARVM_lookup(0u);
  if(strcmp(name,"BRANCHUNLESS")==0) return YARVM_lookup(1u);
  if(strcmp(name,"DUP")==0) return YARVM_lookup(2u);
  if(strcmp(name,"GETLOCAL")==0) return YARVM_lookup(3u);
  if(strcmp(name,"HALT")==0) return YARVM_lookup(4u);
  if(strcmp(name,"JUMP")==0) return YARVM_lookup(5u);
  if(strcmp(name,"LEAVE")==0) return YARVM_lookup(6u);
  if(strcmp(name,"NEWARRAY2")==0) return YARVM_lookup(7u);
  if(strcmp(name,"OPT_AREF")==0) return YARVM_lookup(8u);
  if(strcmp(name,"OPT_EQ")==0) return YARVM_lookup(9u);
  if(strcmp(name,"OPT_MINUS")==0) return YARVM_lookup(10u);
  if(strcmp(name,"OPT_MULT")==0) return YARVM_lookup(11u);
  if(strcmp(name,"OPT_PLUS")==0) return YARVM_lookup(12u);
  if(strcmp(name,"POP")==0) return YARVM_lookup(13u);
  if(strcmp(name,"PRINT")==0) return YARVM_lookup(14u);
  if(strcmp(name,"PUTFALSE")==0) return YARVM_lookup(15u);
  if(strcmp(name,"PUTNIL")==0) return YARVM_lookup(16u);
  if(strcmp(name,"PUTOBJECT")==0) return YARVM_lookup(17u);
  if(strcmp(name,"PUTSELF")==0) return YARVM_lookup(18u);
  if(strcmp(name,"PUTTRUE")==0) return YARVM_lookup(19u);
  if(strcmp(name,"SEND1")==0) return YARVM_lookup(20u);
  if(strcmp(name,"SETLOCAL")==0) return YARVM_lookup(21u);
  return NULL;
}
/* Caller-owned output, transactional validation, labels are instruction indices. */
int YARVM_compile(const char *source, YARVM_tape *out) {
  YARVM_vw_label labels[256]; size_t label_count=0, count=0, total=0, pass;
  char token[128];
  if(!source || !out || out->size>out->capacity || (out->capacity && !out->data)) return -1;
  for(pass=0;pass<3;++pass) {
    const char *cursor=source; int got; count=0;
    while((got=YARVM_vw_token(&cursor,token,sizeof(token)))>0) {
      size_t len=strlen(token), j; const YARVM_metadata *info;
      if(len && token[len-1]==':') {
        token[len-1]=0; if(!token[0]) return -4;
        if(pass==0) {
          if(label_count==256) return -3;
          for(j=0;j<label_count;++j) if(strcmp(labels[j].name,token)==0) return -4;
          strcpy(labels[label_count].name,token); labels[label_count++].address=count;
        }
        continue;
      }
      info=YARVM_vw_mnemonic(token); if(!info) return -4;
      if(count>=out->capacity) return -3;
      if(pass==2) {memset(&out->data[count],0,sizeof(out->data[count]));
        out->data[count].opcode=info->opcode; out->data[count].operand_count=info->operands;}
      for(j=0;j<info->operands;++j) {
        YARVM_cell value=0; char *end; intmax_t parsed;
        if(YARVM_vw_token(&cursor,token,sizeof(token))!=1) return -4;
        if(token[0]=='&') {
          size_t k;
          if(pass) {for(k=0;k<label_count && strcmp(labels[k].name,token+1)!=0;++k) {} if(k==label_count) return -4; value=(YARVM_cell)labels[k].address;}
        } else {
          errno=0; parsed=strtoimax(token,&end,0);
          if(errno || *end || end==token || (intmax_t)(YARVM_cell)parsed!=parsed) return -4;
          value=(YARVM_cell)parsed;
        }
        if(pass && YARVM_vw_label_operand(info->opcode,j) && (uintmax_t)value>=total) return -4;
        if(pass==2) out->data[count].operands[j]=value;
      }
      ++count;
    }
    if(got<0) return -4;
    if(pass==0) total=count;
  }
  out->size=count; return 0;
}

/* .tape */
int YARVM_tape_validate(const YARVM_tape *tape) {
  size_t i;
  if(!tape || tape->size>tape->capacity || (tape->size && !tape->data)) return -1;
  for(i=0;i<tape->size;++i) if(YARVM_vw_validate_instruction(&tape->data[i],tape->size)) return -4;
  return 0;
}

/* .frame */
int YARVM_call(YARVM_vm *vm, YARVM_cell target) {
  YARVM_activation *frame;
  if(!vm || vm->vw_error) return vm ? vm->vw_error : -1;
  if((uintmax_t)target>=vm->vw_code_size) { YARVM_vw_fail(vm,-4); return -4; }
  if(vm->vw_frame_count>=sizeof(vm->vw_frames)/sizeof(vm->vw_frames[0])) { YARVM_vw_fail(vm,-3); return -3; }
  frame=&vm->vw_frames[vm->vw_frame_count++]; memset(frame,0,sizeof(*frame));
  frame->return_address=vm->vw_pc; frame->stack_base=vm->vw_sp; vm->vw_pc=(size_t)target; return 0;
}
int YARVM_ret(YARVM_vm *vm) {
  if(!vm || vm->vw_error) return vm ? vm->vw_error : -1;
  if(!vm->vw_frame_count) { YARVM_vw_fail(vm,-2); return -2; }
  vm->vw_pc=vm->vw_frames[--vm->vw_frame_count].return_address; return 0;
}
